    @org.springframework.data.convert.WritingConverter
    static final class CountingWriter implements org.springframework.core.convert.converter.Converter<String,String>{final java.util.concurrent.atomic.AtomicInteger count;CountingWriter(java.util.concurrent.atomic.AtomicInteger count){this.count=count;}public String convert(String value){count.incrementAndGet();return value;}}
    @Test void generatedInsertMatchesRealTemplateConverterPipeline(){var d=new Driver();var count=new java.util.concurrent.atomic.AtomicInteger();var conversions=org.springframework.data.r2dbc.convert.R2dbcCustomConversions.of(PostgresDialect.INSTANCE,new CountingWriter(count));var mapping=new org.springframework.data.r2dbc.mapping.R2dbcMappingContext();mapping.setSimpleTypeHolder(conversions.getSimpleTypeHolder());var converter=new org.springframework.data.r2dbc.convert.MappingR2dbcConverter(mapping,conversions);var template=new R2dbcEntityTemplate(DatabaseClient.create(d),PostgresDialect.INSTANCE,converter);template.insert(new io.fireflysoftware.masters.models.entities.currency.policy.CurrencyPolicyRows.Audit(P,C,P,P,"PUBLISH",1000L,"reader","https://issuer.example")).block();template.insert(new io.fireflysoftware.masters.models.entities.currency.policy.CurrencyPolicyRows.Outbox(P,C,P,P,"{synthetic}",1000L)).block();int standard=count.get();assertTrue(standard>0);count.set(0);var r=assertDoesNotThrow(()->type("repositories.currency.policy.impl.CurrencyPolicyRepositoryImpl").getConstructor(R2dbcEntityTemplate.class).newInstance(template));call(r,"event",P,C,P,"PUBLISH",1000L,"reader","https://issuer.example","{synthetic}").block();assertSame(converter,template.getConverter());assertEquals(standard,count.get());assertEquals(8,standard);}
    final class Caller {
        final Driver driver=new Driver();
        final R2dbcEntityTemplate operations=driver.template();
        final io.fireflysoftware.masters.models.repositories.currency.policy.CurrencyPolicyRepository real=new io.fireflysoftware.masters.models.repositories.currency.policy.impl.CurrencyPolicyRepositoryImpl(operations);
        final Map<String,Function<Object[],Object>> behavior=new HashMap<>();
        final io.fireflysoftware.masters.interfaces.dtos.currency.v1.CurrencyDTO currency=io.fireflysoftware.masters.interfaces.dtos.currency.v1.CurrencyDTO.builder().currencyId(C).isoCode("USD").currencyName("Synthetic Currency").symbol("$").decimalPrecision(2).isMajor(false).status(io.fireflysoftware.masters.interfaces.enums.commons.v1.StatusEnum.ACTIVE).build();
        final io.fireflysoftware.masters.interfaces.dtos.currency.policy.CurrencyPolicyPublishRequest request;
        final io.fireflysoftware.masters.core.services.currency.policy.CurrencyExecutionPolicyService service;
        Caller(){
            var canonical=io.fireflysoftware.masters.core.services.currency.policy.CurrencyPolicyRules.source(currency);
            request=new io.fireflysoftware.masters.interfaces.dtos.currency.policy.CurrencyPolicyPublishRequest(P.toString(),C.toString(),"USD",canonical.digest(),0L,2,System.currentTimeMillis()-1000,null,"sandbox");
            behavior.put("actionGate",a->Mono.empty());behavior.put("gates",a->Mono.empty());behavior.put("action",a->Mono.empty());behavior.put("currency",a->Mono.just(currency));behavior.put("ensureBinding",a->Mono.empty());behavior.put("binding",a->Mono.just(new io.fireflysoftware.masters.models.repositories.currency.policy.CurrencyPolicyRepository.Binding(C,"USD",0L)));behavior.put("claim",a->real.claim((io.fireflysoftware.masters.models.repositories.currency.policy.CurrencyPolicyRepository.Action)a[0]));
            var api=io.fireflysoftware.masters.models.repositories.currency.policy.CurrencyPolicyRepository.class;
            var controlled=(io.fireflysoftware.masters.models.repositories.currency.policy.CurrencyPolicyRepository)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{api},(proxy,method,args)->method.getName().equals("usesOperations")?real.usesOperations((R2dbcEntityTemplate)args[0]):behavior.containsKey(method.getName())?behavior.get(method.getName()).apply(args):Mono.error(new AssertionError("Unexpected subscribed operation "+method.getName())));
            var context=new io.fireflysoftware.masters.core.services.currency.policy.CurrencyPolicyDatabaseContext(operations){@Override public Mono<Void> establish(org.fireflyframework.security.api.domain.SecurityPrincipal actor,UUID id,String purpose){return Mono.empty();}};
            var authority=new io.fireflysoftware.masters.core.services.currency.policy.CurrencyPolicyAuthority(null,null,null){@Override public Mono<org.fireflyframework.security.api.domain.SecurityPrincipal> authorize(String operation,String id,Map<String,Object> values){return Mono.just(org.fireflyframework.security.api.domain.SecurityPrincipal.builder().subject("synthetic-reader").issuer("https://synthetic.invalid").claims(Map.of("exp",java.time.Instant.now().plusSeconds(120))).build());}};
            service=new io.fireflysoftware.masters.core.services.currency.policy.impl.CurrencyExecutionPolicyServiceImpl(controlled,context,new org.springframework.r2dbc.connection.R2dbcTransactionManager(driver),authority,operations);
        }
        void conflict(){var error=assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.publish(request).block());assertEquals(409,error.getStatusCode().value());assertEquals(1,driver.rollbacks);assertEquals(0,driver.commits);}
    }
